```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, count(*) AS samples, round(avg(value),2) AS avg_value, min(time) AS first_seen, max(time) AS last_seen FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'rate-%' AND metric IN ('k8s.container.ready','k8s.container.restarts','k8s.pod.phase') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Abnormal rate pod rate-7fd7f59946-xr96l stays not ready (ready avg 0.0) with restarts averaging 5.1 across the window."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, count(*) AS n, round(avg(duration)/1e6,3) AS avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1",
          "claim": "All 450 search calls to rate.Rate/GetRates return Error in about 0.02 ms; normal calls took about 3.9 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) AS server_spans FROM abnormal_traces WHERE service_name='rate' GROUP BY 1",
          "claim": "rate emits no spans at all in the abnormal window, while it had 459 server spans in normal."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' GROUP BY 1,2,3",
          "claim": "Search logs 725 errors 'Failed to get rates from rate service' during the incident window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n, round(avg(duration)/1e6,3) AS avg_ms FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Client' AND span_name='rate.Rate/GetRates' GROUP BY 1,2",
          "claim": "Search's GetRates client spans to rate all fail immediately, 450 of 450 in the abnormal window."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby') GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "search.Search/Nearby fails on all 450 server spans, and frontend's client calls to it fail 497 of 500 times."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, round(quantile_cont(duration,0.5)/1e6,2) AS p50_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /hotels' GROUP BY 1",
          "claim": "User-facing HTTP /hotels requests fail 497 of 500 times in the abnormal window, versus 0 errors in normal."
        }
      ]
    }
  ]
}
